import type { Dialogue, GrammarPoint, Reading, Sentence } from '../types'

/**
 * Lesson-level companion material for HSK Standard Course 3 and 4.
 * Lesson order and topics follow the books; explanations, passages, questions,
 * dialogue, pinyin, and Vietnamese translations are original site material.
 * Grammar point mapping was cross-checked against the lesson-indexed HSK 3/4
 * grammar lists below; those lists are secondary references, not publisher files.
 * HSK University reports 97 HSK4 points; this module maps 96 identifiable
 * lesson headings from its page. HSK4B order remains secondary/unverified.
 *
 * Sources:
 * https://www.hskstandardcourse.com/hsk-standard-course-level-3/hsk-standard-course-3-textbook/
 * https://www.hskstandardcourse.com/hsk-standard-course-level-4/hsk-standard-course-4a-textbook/
 * https://www.hskstandardcourse.com/hsk-standard-course-level-4/hsk-standard-course-4b-textbook/
 * https://hskuniversity.com/hsk-3/grammar/
 * https://hskuniversity.com/hsk-4/grammar/
 */

type GSeed = [title: string, pattern: string, explanation: string, hanzi: string, pinyin: string, vi: string]
type LineSeed = [speaker: string, hanzi: string, pinyin: string, vi: string]
type ReadSeed = [hanzi: string, pinyin: string, vi: string]

export interface TextbookLessonMaterial34 {
  grammar: GrammarPoint[]
  dialogues: Dialogue[]
  readings: Reading[]
  sections: string[]
  exercises: string[]
  confusables: ConfusablePair[]
}

export interface ConfusablePair {
  a: string
  b: string
  difference: string
  examples: Sentence[]
}

type DraftMaterial34 = Omit<TextbookLessonMaterial34, 'exercises' | 'confusables'>

const point = (id: string, [title, pattern, explanation, hanzi, pinyin, vi]: GSeed): GrammarPoint => ({
  id, title, pattern, explanation, examples: [{ hanzi, pinyin, vi }],
  drills: [
    { type: 'order', vi, tokens: [...hanzi.replace(/[，。！？、；：]/g, '')], pinyin },
    { type: 'translate', vi, hanzi, pinyin },
  ],
})

const dialog = (id: string, title: string, scene: string, lines: LineSeed[]): Dialogue => ({
  id, title, scene, lines: lines.map(([speaker, hanzi, pinyin, vi]) => ({ speaker, hanzi, pinyin, vi })),
})

const reading = (id: string, title: string, sentences: ReadSeed[], q: string, choices: string[], answer: number, explain: string): Reading => ({
  id, title, sentences: sentences.map(([hanzi, pinyin, vi]): Sentence => ({ hanzi, pinyin, vi })),
  questions: [{ q, choices, answer, explain }],
})

const hsk3: DraftMaterial34[] = [
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-01-text','周末计划','Hai người thống nhất kế hoạch cuối tuần.',[['A','周末你有什么打算？','Zhōumò nǐ yǒu shénme dǎsuàn?','Cuối tuần bạn dự định làm gì?'],['B','我想好去哪儿了，想跟你一起去爬山。','Wǒ xiǎng hǎo qù nǎr le, xiǎng gēn nǐ yìqǐ qù páshān.','Tôi đã nghĩ xong sẽ đi đâu rồi, muốn cùng bạn leo núi.'],['A','好啊，那我们早点儿出发。','Hǎo a, nà wǒmen zǎodiǎnr chūfā.','Được đó, vậy chúng ta xuất phát sớm nhé.']])], readings: [], grammar: [point('hsk3-01-g1',['Bổ ngữ kết quả 好/完','V + 好/完 (+ O)','好 nhấn mạnh việc đã chuẩn bị xong; 完 nhấn mạnh hành động đã kết thúc.','我已经想好了。','Wǒ yǐjīng xiǎng hǎo le.','Tôi đã nghĩ xong rồi.']),point('hsk3-01-g2',['Phủ định toàn bộ 一…也/都不/没…','一 + lượng từ + N + 也/都 + 不/没 + V','Mẫu này nhấn mạnh không có dù chỉ một đối tượng hoặc việc nào.','周末我一天也不想工作。','Zhōumò wǒ yì tiān yě bù xiǎng gōngzuò.','Cuối tuần tôi không muốn làm việc dù chỉ một ngày.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-02-text','什么时候回来','Hỏi giờ về và sắp xếp việc đón.',[['A','你哥哥什么时候回来？','Nǐ gēge shénme shíhou huílai?','Khi nào anh trai bạn về?'],['B','他下了飞机就给我打电话。','Tā xià le fēijī jiù gěi wǒ dǎ diànhuà.','Anh ấy xuống máy bay là gọi cho tôi ngay.'],['A','那我跟你一起去接他。','Nà wǒ gēn nǐ yìqǐ qù jiē tā.','Vậy tôi đi đón anh ấy cùng bạn.']])], readings: [], grammar: [point('hsk3-02-g1',['Bổ ngữ xu hướng đơn giản','V + 来/去','来 chỉ hướng về phía người nói; 去 chỉ hướng rời xa người nói.','他什么时候回来？','Tā shénme shíhou huílai?','Khi nào anh ấy quay về?']),point('hsk3-02-g2',['Hai hành động nối tiếp','V1 + 了 + O + 就 + V2','就 nối hành động sau xảy ra ngay sau hành động trước.','我下了课就回家。','Wǒ xià le kè jiù huí jiā.','Tôi tan học là về nhà ngay.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-03-text','桌上的饮料','Khách hỏi đồ uống đặt trên bàn.',[['A','桌子上放着很多饮料，你想喝什么？','Zhuōzi shang fàngzhe hěn duō yǐnliào, nǐ xiǎng hē shénme?','Trên bàn có nhiều đồ uống, bạn muốn uống gì?'],['B','有茶或者果汁吗？','Yǒu chá huòzhě guǒzhī ma?','Có trà hoặc nước ép không?'],['A','都有，你自己选吧。','Dōu yǒu, nǐ zìjǐ xuǎn ba.','Đều có, bạn tự chọn nhé.']])], readings: [], grammar: [point('hsk3-03-g1',['Câu tồn tại với 着','Địa điểm + V + 着 + N','着 mô tả người/vật đang ở trạng thái hoặc vị trí nào đó.','桌子上放着两杯茶。','Zhuōzi shang fàngzhe liǎng bēi chá.','Trên bàn có đặt hai cốc trà.']),point('hsk3-03-g2',['或者 trong câu kể','A + 或者 + B','或者 nối các lựa chọn trong câu kể; câu hỏi lựa chọn thường dùng 还是.','我喝茶或者水都可以。','Wǒ hē chá huòzhě shuǐ dōu kěyǐ.','Tôi uống trà hay nước đều được.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-04-text','跟客人说话','Mô tả cách một nhân viên tiếp khách.',[['A','她怎么总是笑着跟客人说话？','Tā zěnme zǒngshì xiàozhe gēn kèrén shuōhuà?','Sao cô ấy lúc nào cũng vừa cười vừa nói chuyện với khách?'],['B','她觉得客人又友好又有意思。','Tā juéde kèrén yòu yǒuhǎo yòu yǒu yìsi.','Cô ấy thấy khách vừa thân thiện vừa thú vị.']])], readings: [], grammar: [point('hsk3-04-g1',['Động tác đi kèm 着','V1 + 着 + V2','Động từ thứ nhất mô tả tư thế/cách thức khi thực hiện động từ chính.','她笑着回答问题。','Tā xiàozhe huídá wèntí.','Cô ấy mỉm cười trả lời câu hỏi.']),point('hsk3-04-g2',['Hai đặc điểm 又…又…','又 + A + 又 + B','Nối hai đặc điểm cùng đúng về một người hoặc sự vật.','这家店又干净又安静。','Zhè jiā diàn yòu gānjìng yòu ānjìng.','Cửa hàng này vừa sạch vừa yên tĩnh.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-05-text','最近的变化','Hai người nhận xét thời tiết và thói quen.',[['A','你最近怎么越来越瘦了？','Nǐ zuìjìn zěnme yuèláiyuè shòu le?','Sao dạo này bạn ngày càng gầy vậy?'],['B','我开始每天走路，身体也越来越好了。','Wǒ kāishǐ měitiān zǒulù, shēntǐ yě yuèláiyuè hǎo le.','Tôi bắt đầu đi bộ mỗi ngày, sức khỏe cũng ngày càng tốt hơn.']])], readings: [], grammar: [point('hsk3-05-g1',['Thay đổi tăng dần 越来越','越来越 + tính từ/động từ tâm lý','Diễn tả mức độ thay đổi dần theo thời gian.','天气越来越暖和了。','Tiānqì yuèláiyuè nuǎnhuo le.','Thời tiết ngày càng ấm lên.']),point('hsk3-05-g2',['了 biểu thị thay đổi','Câu + 了','了 cuối câu báo một trạng thái mới hoặc sự thay đổi so với trước.','我现在不累了。','Wǒ xiànzài bú lèi le.','Bây giờ tôi không mệt nữa.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-06-text','突然找不到','Hai người tìm đồ thất lạc.',[['A','我的钥匙怎么突然找不到了？','Wǒ de yàoshi zěnme tūrán zhǎo bú dào le?','Sao tự nhiên tôi không tìm thấy chìa khóa nữa?'],['B','别着急，你再想想放在哪儿了。','Bié zháojí, nǐ zài xiǎngxiang fàng zài nǎr le.','Đừng vội, bạn nghĩ lại xem đã để ở đâu.'],['A','我想起来了，在门口的桌子上。','Wǒ xiǎng qǐlai le, zài ménkǒu de zhuōzi shang.','Tôi nhớ ra rồi, ở trên bàn cạnh cửa.']])], readings: [], grammar: [point('hsk3-06-g1',['Bổ ngữ khả năng','V + 得/不 + bổ ngữ kết quả/xu hướng','得 cho biết đạt được kết quả; 不 cho biết không đạt được.','这个字我看得懂。','Zhège zì wǒ kàn de dǒng.','Chữ này tôi đọc hiểu được.']),point('hsk3-06-g2',['Khả năng với 下','V + 得/不 + 下','下 biểu thị sức chứa hoặc khả năng tiếp nhận vừa đủ/không đủ.','这么多菜，我们吃不下。','Zhème duō cài, wǒmen chī bu xià.','Nhiều món thế này, chúng tôi ăn không hết.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-07-text','认识五年了','Bạn bè nhắc thời gian quen nhau.',[['A','你跟小王认识多长时间了？','Nǐ gēn Xiǎo Wáng rènshi duō cháng shíjiān le?','Bạn quen Tiểu Vương bao lâu rồi?'],['B','我们认识五年了，都喜欢运动。','Wǒmen rènshi wǔ nián le, dōu xǐhuan yùndòng.','Chúng tôi quen nhau năm năm rồi, đều thích thể thao.'],['A','你们对什么运动最感兴趣？','Nǐmen duì shénme yùndòng zuì gǎn xìngqù?','Hai bạn thích môn thể thao nào nhất?']])], readings: [], grammar: [point('hsk3-07-g1',['Thời lượng đến hiện tại','V + thời lượng + 了','Cho biết một trạng thái/hành động đã kéo dài đến hiện tại.','我在这儿住三年了。','Wǒ zài zhèr zhù sān nián le.','Tôi sống ở đây ba năm rồi.']),point('hsk3-07-g2',['Đối với… có hứng thú','对 + đối tượng + 感兴趣','感兴趣 đứng sau 对 và tân ngữ để nêu điều mình quan tâm.','她对中国历史很感兴趣。','Tā duì Zhōngguó lìshǐ hěn gǎn xìngqù.','Cô ấy rất hứng thú với lịch sử Trung Quốc.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-08-text','你去哪儿我就去哪儿','Hai người quyết định đi cùng nhau.',[['A','你周末想去哪儿？','Nǐ zhōumò xiǎng qù nǎr?','Cuối tuần bạn muốn đi đâu?'],['B','你去哪儿我就去哪儿。','Nǐ qù nǎr wǒ jiù qù nǎr.','Bạn đi đâu thì tôi đi đó.'],['A','那我们去看电影吧。','Nà wǒmen qù kàn diànyǐng ba.','Vậy chúng ta đi xem phim nhé.']])], readings: [], grammar: [point('hsk3-08-g1',['Đại từ nghi vấn dùng phiếm chỉ','Từ hỏi + 就 + từ hỏi','Từ hỏi lặp lại ở hai vế diễn tả “ai/đâu/cái gì… thì…”.','你想吃什么就点什么。','Nǐ xiǎng chī shénme jiù diǎn shénme.','Bạn muốn ăn gì thì gọi món đó.']),point('hsk3-08-g2',['Lặp lại việc: 又 và 再','又 + V (đã xảy ra); 再 + V (sẽ làm lại)','又 thường nói việc lặp lại đã xảy ra; 再 thường nói dự định lặp lại.','昨天我去了，明天我再去。','Zuótiān wǒ qù le, míngtiān wǒ zài qù.','Hôm qua tôi đã đi, ngày mai tôi sẽ đi lại.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-09-text','说得一样好','Người học so sánh khả năng nói tiếng Trung.',[['A','你汉语说得真好。','Nǐ Hànyǔ shuō de zhēn hǎo.','Bạn nói tiếng Trung hay thật.'],['B','我还要多练习，希望说得跟你一样自然。','Wǒ hái yào duō liànxí, xīwàng shuō de gēn nǐ yíyàng zìrán.','Tôi còn phải luyện nhiều, mong nói tự nhiên như bạn.']])], readings: [], grammar: [point('hsk3-09-g1',['So sánh ngang bằng với 跟…一样','A + 跟 + B + 一样 + tính từ','Đặt đặc điểm sau 一样 để nói hai bên ngang bằng về đặc điểm ấy.','她跑得跟我一样快。','Tā pǎo de gēn wǒ yíyàng kuài.','Cô ấy chạy nhanh bằng tôi.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-10-text','比历史难多了','Hai bạn trao đổi về môn học.',[['A','你觉得数学怎么样？','Nǐ juéde shùxué zěnmeyàng?','Bạn thấy môn toán thế nào?'],['B','数学比历史难多了，不过很有意思。','Shùxué bǐ lìshǐ nán duō le, búguò hěn yǒu yìsi.','Toán khó hơn lịch sử nhiều, nhưng rất thú vị.']])], readings: [], grammar: [point('hsk3-10-g1',['Nhấn mạnh mức độ so sánh','A + 比 + B + tính từ + 多了/得多','多了 hoặc 得多 nhấn mạnh chênh lệch lớn.','今天比昨天冷得多。','Jīntiān bǐ zuótiān lěng de duō.','Hôm nay lạnh hơn hôm qua nhiều.']),point('hsk3-10-g2',['Số lượng ước chừng','Số lượng + 左右','左右 đặt sau con số để diễn tả xấp xỉ.','从这儿到学校要二十分钟左右。','Cóng zhèr dào xuéxiào yào èrshí fēnzhōng zuǒyòu.','Từ đây đến trường mất khoảng 20 phút.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-11-text','关空调','Nhắc người nhà xử lý đồ vật trước khi rời phòng.',[['A','出门以前，别忘了把空调关了。','Chūmén yǐqián, bié wàng le bǎ kōngtiáo guān le.','Trước khi ra ngoài, đừng quên tắt điều hòa.'],['B','我知道了，也把窗户关上。','Wǒ zhīdào le, yě bǎ chuānghu guān shang.','Tôi biết rồi, cũng đóng cửa sổ lại.']])], readings: [], grammar: [point('hsk3-11-g1',['Câu 把 cơ bản','Chủ ngữ + 把 + tân ngữ + động từ + kết quả','把 đưa đối tượng xác định lên trước động từ để nêu cách xử lý/tác động lên nó.','请把灯关了。','Qǐng bǎ dēng guān le.','Làm ơn tắt đèn đi.']),point('hsk3-11-g2',['Ước lượng với 左右','Số + 左右','左右 theo sau lượng từ hoặc mốc thời gian để chỉ con số gần đúng.','会议开了一个小时左右。','Huìyì kāi le yí ge xiǎoshí zuǒyòu.','Cuộc họp kéo dài khoảng một tiếng.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-12-text','放在我这儿','Một người nhờ giữ đồ quan trọng.',[['A','这些重要的东西我该放在哪儿？','Zhèxiē zhòngyào de dōngxi wǒ gāi fàng zài nǎr?','Tôi nên để những đồ quan trọng này ở đâu?'],['B','你把它们放在我这儿吧，我会看好的。','Nǐ bǎ tāmen fàng zài wǒ zhèr ba, wǒ huì kàn hǎo de.','Bạn cứ để chúng ở chỗ tôi, tôi sẽ trông cẩn thận.']])], readings: [], grammar: [point('hsk3-12-g1',['Câu 把 với kết quả/vị trí','S + 把 + O + V + 在/到/给…','Sau động từ cần nêu kết quả, hướng hoặc nơi nhận của đối tượng.','请把书放在桌子上。','Qǐng bǎ shū fàng zài zhuōzi shang.','Hãy đặt sách lên bàn.']),point('hsk3-12-g2',['才 và 就 chỉ thời điểm','Thời gian + 才/就 + V','才 thường gợi muộn hơn dự kiến; 就 gợi sớm hoặc nhanh hơn dự kiến.','他九点才到，我八点就到了。','Tā jiǔ diǎn cái dào, wǒ bā diǎn jiù dào le.','Chín giờ anh ấy mới đến, còn tôi đã đến từ tám giờ.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-13-text','走回来','Kể lại quãng đường đi bộ về nhà.',[['A','你怎么回来的？','Nǐ zěnme huílai de?','Bạn về bằng cách nào?'],['B','我是从地铁站走回来的，路上还买了水果。','Wǒ shì cóng dìtiězhàn zǒu huílai de, lùshang hái mǎi le shuǐguǒ.','Tôi đi bộ từ ga tàu điện về, trên đường còn mua trái cây.']])], readings: [], grammar: [point('hsk3-13-g1',['Bổ ngữ xu hướng kép','V + hướng + 来/去','来/去 đặt cuối cụm hướng để xác định chuyển động về phía/ra xa điểm nhìn.','他从楼上跑下来了。','Tā cóng lóushàng pǎo xiàlai le.','Anh ấy chạy từ trên lầu xuống đây.']),point('hsk3-13-g2',['Câu 是…的 nhấn mạnh cách thức','是 + thành phần nhấn mạnh + V + 的','Dùng 是…的 để nhấn mạnh thời gian, nơi chốn hoặc cách thức của việc đã xảy ra.','我是坐公共汽车来的。','Wǒ shì zuò gōnggòng qìchē lái de.','Tôi đến bằng xe buýt.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-14-text','拿水果过来','Nhờ người khác mang trái cây đến.',[['A','请把桌子上的水果拿过来。','Qǐng bǎ zhuōzi shang de shuǐguǒ ná guòlai.','Làm ơn mang trái cây trên bàn lại đây.'],['B','好的，我马上拿过来。','Hǎo de, wǒ mǎshàng ná guòlai.','Được, tôi mang lại ngay.']])], readings: [], grammar: [point('hsk3-14-g1',['把 với bổ ngữ xu hướng','S + 把 + O + V + 来/去','Nêu đối tượng được di chuyển và hướng di chuyển của nó.','把那本书拿过来。','Bǎ nà běn shū ná guòlai.','Mang quyển sách kia lại đây.']),point('hsk3-14-g2',['Nêu thứ tự 先…然后…','先 + V1，然后 + V2','先 giới thiệu việc trước, 然后 giới thiệu việc tiếp theo.','我们先吃饭，然后去看电影。','Wǒmen xiān chīfàn, ránhòu qù kàn diànyǐng.','Chúng ta ăn trước, sau đó đi xem phim.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-15-text','其他都没问题','Kiểm tra tình hình chuẩn bị cho buổi gặp.',[['A','大家都准备好了吗？','Dàjiā dōu zhǔnbèi hǎo le ma?','Mọi người chuẩn bị xong chưa?'],['B','其他都没有问题，就是小李还没到。','Qítā dōu méiyǒu wèntí, jiùshì Xiǎo Lǐ hái méi dào.','Những thứ khác đều ổn, chỉ là Tiểu Lý chưa tới.']])], readings: [], grammar: [point('hsk3-15-g1',['Ngoại trừ với 除了…以外','除了 + A + 以外，…都/还…','都 diễn tả phần còn lại đều đúng; 还 có thể bổ sung thêm một ý.','除了茶以外，我还想喝水。','Chúle chá yǐwài, wǒ hái xiǎng hē shuǐ.','Ngoài trà ra, tôi còn muốn uống nước.']),point('hsk3-15-g2',['Từ nghi vấn mang nghĩa phiếm chỉ','Từ hỏi + 都/也 + phủ định/khẳng định','什/谁/哪 kết hợp 都/也 để nói mọi thứ/mọi người hoặc không gì/không ai.','其他我都明白了。','Qítā wǒ dōu míngbai le.','Những điều khác tôi đều hiểu rồi.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-16-text','累得想睡觉','Hai đồng nghiệp nói chuyện sau giờ làm.',[['A','你今天怎么这么累？','Nǐ jīntiān zěnme zhème lèi?','Sao hôm nay bạn mệt thế?'],['B','我累得下了班就想睡觉。','Wǒ lèi de xià le bān jiù xiǎng shuìjiào.','Tôi mệt đến mức tan làm là chỉ muốn ngủ.'],['A','那你回家以后早点儿休息。','Nà nǐ huí jiā yǐhòu zǎodiǎnr xiūxi.','Vậy về nhà rồi nghỉ sớm nhé.']])], readings: [], grammar: [point('hsk3-16-g1',['Bổ ngữ mức độ với 得','Tính từ/động từ + 得 + kết quả/mức độ','得 nối động từ hoặc tính từ với phần mô tả mức độ/hệ quả.','他高兴得睡不着。','Tā gāoxìng de shuì bu zháo.','Anh ấy vui đến mức không ngủ được.']),point('hsk3-16-g2',['Điều kiện 如果…就…','如果 + điều kiện，就 + kết quả','如果 nêu điều kiện; 就 nêu kết quả tương ứng.','如果太累，就早点儿回家。','Rúguǒ tài lèi, jiù zǎodiǎnr huí jiā.','Nếu mệt quá thì về nhà sớm.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-17-text','看好你的病','Bạn bè chia sẻ cách giữ sức khỏe.',[['A','医生说我应该多运动。','Yīshēng shuō wǒ yīnggāi duō yùndòng.','Bác sĩ nói tôi nên vận động nhiều hơn.'],['B','谁都有办法照顾好自己的身体。','Shéi dōu yǒu bànfǎ zhàogù hǎo zìjǐ de shēntǐ.','Ai cũng có cách chăm sóc tốt sức khỏe của mình.']])], readings: [], grammar: [point('hsk3-17-g1',['Đại từ nghi vấn + 都','谁/什么/哪 + 都 + vị ngữ','Đại từ hỏi kết hợp 都 có thể mang nghĩa khái quát “ai/cái gì/đâu cũng…”.','谁都可以参加。','Shéi dōu kěyǐ cānjiā.','Ai cũng có thể tham gia.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-18-text','我相信他们会同意','Trao đổi về một đề xuất trong nhóm.',[['A','你觉得他们会同意这个办法吗？','Nǐ juéde tāmen huì tóngyì zhège bànfǎ ma?','Bạn nghĩ họ sẽ đồng ý cách này chứ?'],['B','我相信大家会认真考虑的。','Wǒ xiāngxìn dàjiā huì rènzhēn kǎolǜ de.','Tôi tin mọi người sẽ cân nhắc nghiêm túc.']])], readings: [], grammar: [point('hsk3-18-g1',['会 biểu thị dự đoán','Chủ ngữ + 会 + động từ','会 có thể biểu thị khả năng hoặc dự đoán một việc sẽ xảy ra.','明天他们会来的。','Míngtiān tāmen huì lái de.','Ngày mai họ sẽ đến thôi.']),point('hsk3-18-g2',['的 ở cuối câu để xác nhận','Mệnh đề + 的','的 cuối câu có thể thể hiện sự khẳng định hoặc niềm tin của người nói.','我知道他会来的。','Wǒ zhīdào tā huì lái de.','Tôi biết anh ấy sẽ đến mà.'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-19-text','看出来了吗','Nhận xét một thay đổi dễ nhận ra.',[['A','你看出来她换发型了吗？','Nǐ kàn chūlai tā huàn fàxíng le ma?','Bạn có nhận ra cô ấy đổi kiểu tóc không?'],['B','看出来了，她的新发型很适合她。','Kàn chūlai le, tā de xīn fàxíng hěn shìhé tā.','Nhận ra rồi, kiểu tóc mới rất hợp với cô ấy.']])], readings: [], grammar: [point('hsk3-19-g1',['Bổ ngữ kết quả 出来','V + 出来','出来 có thể biểu thị kết quả nhận ra, phát hiện hoặc tạo ra điều gì.','我听出来这是他的声音。','Wǒ tīng chūlai zhè shì tā de shēngyīn.','Tôi nghe ra đây là giọng của anh ấy.']),point('hsk3-19-g2',['Câu hỏi tu từ với 难道','难道 + mệnh đề + 吗？','难道 tạo câu hỏi tu từ, thường hàm ý người nói đã có câu trả lời.','你难道不知道吗？','Nǐ nándào bù zhīdào ma?','Chẳng lẽ bạn không biết sao?'])] },
  { sections: ['课文 · Bài khóa', '生词 · Từ mới', '语言点 · Điểm ngôn ngữ', '练习 · Bài tập'], dialogues: [dialog('hsk3-20-text','受到影响','Hai người kể về ảnh hưởng của một người thầy.',[['A','你为什么开始喜欢读书了？','Nǐ wèishénme kāishǐ xǐhuan dúshū le?','Vì sao bạn bắt đầu thích đọc sách?'],['B','我以前不爱读书，后来受老师影响，慢慢喜欢上了。','Wǒ yǐqián bú ài dúshū, hòulái shòu lǎoshī yǐngxiǎng, mànman xǐhuan shàng le.','Trước đây tôi không thích đọc, sau chịu ảnh hưởng của thầy nên dần dần thích đọc.']])], readings: [], grammar: [point('hsk3-20-g1',['Câu bị động với 被','Đối tượng + 被 + tác nhân + động từ','Đưa đối tượng chịu tác động lên đầu câu; tác nhân có thể lược bỏ.','我的想法被大家接受了。','Wǒ de xiǎngfǎ bèi dàjiā jiēshòu le.','Ý kiến của tôi đã được mọi người chấp nhận.'])] },
]

const hsk4: DraftMaterial34[] = [
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · theo đối chiếu thứ cấp', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-01-text','理解彼此',[['相爱的人不一定有相同的爱好。','Xiāng ài de rén bù yídìng yǒu xiāngtóng de àihào.','Những người yêu nhau chưa chắc có cùng sở thích.']], '两个人相处时，什么很重要？', ['只谈浪漫','互相理解','收入一样','住得很近'],1,'Đoạn văn nhấn mạnh việc thấu hiểu và giao tiếp.')], grammar: [point('hsk4-01-g1',['不仅…也/还/而且…','不仅 A，也/还/而且 B','Vế sau bổ sung thêm một ý cùng hướng, thường nhấn mạnh thêm đặc điểm.','爱情不仅需要浪漫，也需要理解。','Àiqíng bùjǐn xūyào làngmàn, yě xūyào lǐjiě.','Tình yêu không chỉ cần lãng mạn mà còn cần thấu hiểu.']),point('hsk4-01-g2',['从来','从来 + 不/没 + V','从来 thường đi với 不/没 để nói một việc chưa từng hoặc vốn luôn như vậy.','他从来不把工作带回家。','Tā cónglái bù bǎ gōngzuò dài huí jiā.','Anh ấy trước nay không mang việc về nhà.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · theo đối chiếu thứ cấp', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-02-text','真正的朋友',[['朋友不一定每天见面，但是遇到困难时会互相帮助。','Péngyou bù yídìng měitiān jiànmiàn, dànshì yùdào kùnnan shí huì hùxiāng bāngzhù.','Bạn bè không nhất thiết gặp nhau mỗi ngày, nhưng sẽ giúp đỡ nhau khi gặp khó khăn.'],['有空的时候，我们常常打电话，也会约着一起散步。','Yǒu kòng de shíhou, wǒmen chángcháng dǎ diànhuà, yě huì yuēzhe yìqǐ sànbù.','Lúc rảnh, chúng tôi thường gọi điện và hẹn nhau đi dạo.']], '朋友怎样保持联系？',['每天见面','有空联系并互相帮助','只在网上聊天','一起工作'],1,'文中提到平时联系、困难时互助。')], grammar: [point('hsk4-02-g1',['正好','正好 + động từ/danh từ','正好 có thể chỉ sự vừa khớp hoặc tình cờ đúng lúc.','我正好有两张票，我们一起去吧。','Wǒ zhènghǎo yǒu liǎng zhāng piào, wǒmen yìqǐ qù ba.','Tôi vừa hay có hai vé, chúng ta cùng đi nhé.']),point('hsk4-02-g2',['尽管…却/但是…','尽管 A，却/但是 B','尽管 nhượng bộ một sự thật; vế sau nêu điều trái dự đoán.','尽管工作很忙，他却常常来看朋友。','Jǐnguǎn gōngzuò hěn máng, tā què chángcháng lái kàn péngyou.','Dù công việc rất bận, anh ấy vẫn thường đến thăm bạn.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · theo đối chiếu thứ cấp', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-03-text','留下好印象',[['经理先听我介绍以前的工作，又问我怎样解决问题。','Jīnglǐ xiān tīng wǒ jièshào yǐqián de gōngzuò, yòu wèn wǒ zěnyàng jiějué wèntí.','Giám đốc nghe tôi giới thiệu công việc trước đây, rồi hỏi tôi xử lý vấn đề thế nào.'],['我本来有些紧张，不过准备得很充分，所以回答得比较清楚。','Wǒ běnlái yǒuxiē jǐnzhāng, búguò zhǔnbèi de hěn chōngfèn, suǒyǐ huídá de bǐjiào qīngchu.','Ban đầu tôi hơi căng thẳng, nhưng chuẩn bị kỹ nên trả lời khá rõ ràng.']], '面试时，“我”为什么回答得清楚？',['问题很简单','准备充分','经理帮忙','以前认识经理'],1,'第二句说明回答清楚与准备充分有关。')], grammar: [point('hsk4-03-g1',['挺…的','挺 + tính từ + 的','挺 diễn tả mức độ khá/cũng; 的 thường khép lại lời nhận xét thân mật.','这份工作挺适合你的。','Zhè fèn gōngzuò tǐng shìhé nǐ de.','Công việc này khá hợp với bạn đấy.']),point('hsk4-03-g2',['本来','本来 + mệnh đề','本来 nêu tình trạng hoặc dự định ban đầu, đôi khi hàm ý sau đó đã thay đổi.','我本来想坐车，后来决定走路。','Wǒ běnlái xiǎng zuò chē, hòulái juédìng zǒulù.','Ban đầu tôi định đi xe, sau đó quyết định đi bộ.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · theo đối chiếu thứ cấp', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-04-text','调整方向',[['他以为换一份工作就能解决所有问题，后来才发现并不是这样。','Tā yǐwéi huàn yí fèn gōngzuò jiù néng jiějué suǒyǒu wèntí, hòulái cái fāxiàn bìng bú shì zhèyàng.','Anh ấy tưởng đổi việc là giải quyết được mọi vấn đề, sau này mới nhận ra không phải vậy.'],['原来，真正需要改变的是自己的工作方法。','Yuánlái, zhēnzhèng xūyào gǎibiàn de shì zìjǐ de gōngzuò fāngfǎ.','Hóa ra điều thực sự cần thay đổi là cách làm việc của chính mình.']], '他后来发现什么需要改变？',['工作地点','工作方法','同事','收入'],1,'Đoạn cuối xác định điều cần thay đổi là phương pháp làm việc.')], grammar: [point('hsk4-04-g1',['以为','以为 + mệnh đề','以为 nêu điều người nói từng nghĩ là đúng, thường hóa ra không đúng.','我以为今天不用开会，原来记错了。','Wǒ yǐwéi jīntiān bú yòng kāihuì, yuánlái jì cuò le.','Tôi tưởng hôm nay không cần họp, hóa ra nhớ nhầm rồi.']),point('hsk4-04-g2',['首先…其次…','首先 A，其次 B','Dùng để trình bày hai lý do hoặc bước theo thứ tự.','首先要了解情况，其次再决定怎么做。','Shǒuxiān yào liǎojiě qíngkuàng, qícì zài juédìng zěnme zuò.','Trước hết cần hiểu tình hình, sau đó mới quyết định làm thế nào.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · theo đối chiếu thứ cấp', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-05-text','选择合适的家具',[['买家具时，不能只看广告，还要注意材料和做工。','Mǎi jiājù shí, bù néng zhǐ kàn guǎnggào, hái yào zhùyì cáiliào hé zuògōng.','Khi mua đồ nội thất, không thể chỉ xem quảng cáo mà còn phải chú ý chất liệu và gia công.'],['价格合适当然重要，质量也要符合自己的需要。','Jiàgé héshì dāngrán zhòngyào, zhìliàng yě yào fúhé zìjǐ de xūyào.','Giá cả phù hợp đương nhiên quan trọng, chất lượng cũng cần đáp ứng nhu cầu.']], '买家具时，除了价格还要注意什么？',['品牌和颜色','材料和做工','送货时间','广告数量'],1,'第一句直接提到材料和做工。')], grammar: [point('hsk4-05-g1',['按照','按照 + danh từ/căn cứ','按照 giới thiệu quy tắc hoặc tiêu chuẩn làm căn cứ để thực hiện.','请按照房间的大小选家具。','Qǐng ànzhào fángjiān de dàxiǎo xuǎn jiājù.','Hãy chọn đồ nội thất theo kích thước căn phòng.']),point('hsk4-05-g2',['甚至','甚至 + thành phần nhấn mạnh','甚至 đưa ra một trường hợp nổi bật hoặc vượt xa điều vừa nêu.','他很喜欢这把椅子，甚至愿意多等一个月。','Tā hěn xǐhuan zhè bǎ yǐzi, shènzhì yuànyì duō děng yí ge yuè.','Anh ấy rất thích chiếc ghế này, thậm chí sẵn lòng đợi thêm một tháng.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · theo đối chiếu thứ cấp', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-06-text','一分钱一分货',[['买东西时，有些人只看价格，有些人更关心质量。','Mǎi dōngxi shí, yǒuxiē rén zhǐ kàn jiàgé, yǒuxiē rén gèng guānxīn zhìliàng.','Khi mua đồ, có người chỉ xem giá, có người quan tâm chất lượng hơn.'],['价格高不一定代表质量好，但便宜的东西也要看材料和做工。','Jiàgé gāo bù yídìng dàibiǎo zhìliàng hǎo, dàn piányi de dōngxi yě yào kàn cáiliào hé zuògōng.','Giá cao chưa chắc chất lượng tốt, nhưng đồ rẻ cũng cần xem chất liệu và gia công.']], '买东西时，作者建议还要看什么？',['广告','材料和做工','包装颜色','品牌名称'],1,'第二句建议检查材料与做工。')], grammar: [point('hsk4-06-g1',['一分钱一分货','一分钱一分货','Thành ngữ nhấn mạnh giá cả thường phản ánh phần nào chất lượng hàng hóa.','这双鞋虽然贵，但是一分钱一分货。','Zhè shuāng xié suīrán guì, dànshì yì fēn qián yì fēn huò.','Đôi giày này tuy đắt nhưng tiền nào của nấy.']),point('hsk4-06-g2',['竟然','Chủ ngữ + 竟然 + động từ/tính từ','竟然 diễn tả kết quả bất ngờ, trái với điều người nói dự đoán.','这么便宜的东西，质量竟然这么好。','Zhème piányi de dōngxi, zhìliàng jìngrán zhème hǎo.','Món đồ rẻ thế mà chất lượng lại tốt đến vậy.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · theo đối chiếu thứ cấp', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-07-text','及时休息',[['医生估计他需要休息一周，不过病情并不严重。','Yīshēng gūjì tā xūyào xiūxi yì zhōu, búguò bìngqíng bìng bù yánzhòng.','Bác sĩ ước tính anh ấy cần nghỉ một tuần, nhưng bệnh tình không nghiêm trọng.'],['他来不及参加比赛，只好在家养病。','Tā láibují cānjiā bǐsài, zhǐhǎo zài jiā yǎng bìng.','Anh ấy không kịp tham gia cuộc thi, đành ở nhà dưỡng bệnh.']], '他为什么没参加比赛？',['病情严重','没有时间准备','来不及参加','不喜欢比赛'],2,'Câu hai nêu anh ấy không kịp tham gia.')], grammar: [point('hsk4-07-g1',['估计','估计 + mệnh đề','估计 diễn tả phỏng đoán dựa trên tình hình hiện tại.','我估计他今天不会来了。','Wǒ gūjì tā jīntiān bú huì lái le.','Tôi đoán hôm nay anh ấy sẽ không đến.']),point('hsk4-07-g2',['来不及','来不及 + động từ','Diễn tả không đủ thời gian để hoàn thành một việc.','时间太晚了，我们来不及买票。','Shíjiān tài wǎn le, wǒmen láibují mǎi piào.','Muộn quá rồi, chúng ta không kịp mua vé.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · theo đối chiếu thứ cấp', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-08-text','为旅程做准备',[['出发前，我们先查天气，再决定带什么衣服。','Chūfā qián, wǒmen xiān chá tiānqì, zài juédìng dài shénme yīfu.','Trước khi xuất phát, chúng tôi xem thời tiết rồi quyết định mang quần áo nào.'],['只要准备充分，旅途中遇到小问题也不会太着急。','Zhǐyào zhǔnbèi chōngfèn, lǚtú zhōng yùdào xiǎo wèntí yě bú huì tài zháojí.','Chỉ cần chuẩn bị đầy đủ, gặp vấn đề nhỏ trên đường cũng không quá lo.']], '出发前他们先做什么？',['买衣服','查天气','订饭店','换钱'],1,'Câu đầu nói trước tiên họ kiểm tra thời tiết.')], grammar: [point('hsk4-08-g1',['使','A + 使 + B + tính từ/động từ','使 diễn tả một việc làm cho người/vật khác thay đổi hoặc hành động.','充分的准备使旅行更轻松。','Chōngfèn de zhǔnbèi shǐ lǚxíng gèng qīngsōng.','Sự chuẩn bị đầy đủ khiến chuyến đi nhẹ nhàng hơn.']),point('hsk4-08-g2',['只要…就…','只要 + điều kiện，就 + kết quả','只要 nêu điều kiện đủ để kết quả ở vế sau xảy ra.','只要早点儿出发，我们就不会迟到。','Zhǐyào zǎodiǎnr chūfā, wǒmen jiù bú huì chídào.','Chỉ cần xuất phát sớm thì chúng ta sẽ không muộn.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · theo đối chiếu thứ cấp', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-09-text','风雨之后',[['遇到困难时，有的人会停下来，有的人会想办法继续走。','Yùdào kùnnan shí, yǒu de rén huì tíng xiàlai, yǒu de rén huì xiǎng bànfǎ jìxù zǒu.','Khi gặp khó khăn, có người dừng lại, có người tìm cách tiếp tục bước đi.'],['通过一次次努力，我们常常能看到新的希望。','Tōngguò yí cì cì nǔlì, wǒmen chángcháng néng kàndào xīn de xīwàng.','Qua từng lần cố gắng, chúng ta thường có thể nhìn thấy hy vọng mới.']], '怎样才能看到新的希望？',['等待别人','通过努力','忘记困难','马上离开'],1,'第二句说明经过努力可以看到希望。')], grammar: [point('hsk4-09-g1',['难道…吗？','难道 + mệnh đề + 吗？','Dùng câu hỏi tu từ để nhấn mạnh điều người nói cho là hiển nhiên.','难道努力没有意义吗？','Nándào nǔlì méiyǒu yìyì ma?','Chẳng lẽ nỗ lực không có ý nghĩa sao?']),point('hsk4-09-g2',['通过','通过 + phương thức + kết quả','通过 nêu phương tiện hoặc cách thức để đạt một kết quả.','通过练习，她提高了听力。','Tōngguò liànxí, tā tígāo le tīnglì.','Thông qua luyện tập, cô ấy cải thiện kỹ năng nghe.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · theo đối chiếu thứ cấp', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-10-text','一起生活',[['两个人一起生活，除了分担家务，也要学会听对方说话。','Liǎng ge rén yìqǐ shēnghuó, chúle fēndān jiāwù, yě yào xuéhuì tīng duìfāng shuōhuà.','Hai người sống cùng nhau ngoài chia sẻ việc nhà còn cần học cách lắng nghe nhau.'],['在我看来，遇到意见不同的时候，认真沟通比争论更有用。','Zài wǒ kànlai, yùdào yìjiàn bù tóng de shíhou, rènzhēn gōutōng bǐ zhēnglùn gèng yǒuyòng.','Theo tôi, khi bất đồng ý kiến, trao đổi nghiêm túc có ích hơn tranh cãi.']], '作者认为意见不同时应该怎么做？',['马上离开','认真沟通','找别人判断','不再说话'],1,'文中建议认真沟通。')], grammar: [point('hsk4-10-g1',['在…看来','在 + người + 看来','Nêu ý kiến từ góc nhìn của một người.','在我看来，互相理解最重要。','Zài wǒ kànlai, hùxiāng lǐjiě zuì zhòngyào.','Theo tôi, thấu hiểu lẫn nhau là quan trọng nhất.']),point('hsk4-10-g2',['由于…','由于 + nguyên nhân，(kết quả)','由于 thường dùng trong văn viết để dẫn nguyên nhân.','由于天气不好，活动改到室内了。','Yóuyú tiānqì bù hǎo, huódòng gǎi dào shìnèi le.','Do thời tiết xấu, hoạt động được chuyển vào trong nhà.'])] },
]

