const hsk4b: DraftMaterial34[] = [
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · HSK University (nguồn thứ cấp), 4B chưa xác minh', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-11-text','读书的意义',[['读书好，因为书能让人了解不同的生活。','Dúshū hǎo, yīnwèi shū néng ràng rén liǎojiě bùtóng de shēnghuó.','Đọc sách có ích vì sách giúp ta hiểu những cuộc sống khác nhau.'],['读好书，还要把读到的内容和自己的经验联系起来。','Dú hǎo shū, hái yào bǎ dú dào de nèiróng hé zìjǐ de jīngyàn liánxì qǐlai.','Đọc sách hay còn cần liên hệ điều đã đọc với trải nghiệm của mình.']], '怎样才能从书中学到更多？',['只读得快','联系自己的经验','只读一种书','记住书名'],1,'第二句说明要联系自身经验。')], grammar: [point('hsk4-11-g1',['不但…而且…','不但 A，而且 B','Vế sau bổ sung thông tin mạnh hơn hoặc có ý nghĩa nổi bật hơn.','读书不但能增加知识，而且能开阔眼界。','Dúshū búdàn néng zēngjiā zhīshi, érqiě néng kāikuò yǎnjiè.','Đọc sách không chỉ tăng kiến thức mà còn mở rộng tầm nhìn.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · HSK University (nguồn thứ cấp), 4B chưa xác minh', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-12-text','用心观察',[['有时候，我们每天经过同一条街，却没有注意身边的变化。','Yǒu shíhou, wǒmen měitiān jīngguò tóng yì tiáo jiē, què méiyǒu zhùyì shēnbiān de biànhuà.','Đôi khi ngày nào ta cũng đi qua một con phố nhưng không để ý những thay đổi xung quanh.'],['慢下来仔细看看，就会发现生活里有很多值得欣赏的地方。','Màn xiàlai zǐxì kànkan, jiù huì fāxiàn shēnghuó li yǒu hěn duō zhídé xīnshǎng de dìfang.','Chậm lại quan sát kỹ, ta sẽ phát hiện nhiều điều đáng trân trọng trong cuộc sống.']], '怎样才能发现身边值得欣赏的地方？',['走得更快','仔细观察','每天换一条路','不看周围'],1,'第二句提出慢下来仔细观察。')], grammar: [point('hsk4-12-g1',['即使…也…','即使 + giả định，也 + kết quả','Nhượng bộ một tình huống giả định nhưng kết quả vẫn không đổi.','即使很忙，也要留一点时间观察生活。','Jíshǐ hěn máng, yě yào liú yìdiǎn shíjiān guānchá shēnghuó.','Dù rất bận cũng nên dành chút thời gian quan sát cuộc sống.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · HSK University (nguồn thứ cấp), 4B chưa xác minh', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-13-text','茶与京剧',[['第一次看京剧时，我听不懂唱词，只觉得演员的动作很有意思。','Dì yí cì kàn Jīngjù shí, wǒ tīng bu dǒng chàngcí, zhǐ juéde yǎnyuán de dòngzuò hěn yǒu yìsi.','Lần đầu xem Kinh kịch, tôi không hiểu lời hát, chỉ thấy động tác diễn viên rất thú vị.'],['朋友一边给我讲故事，一边泡茶，我们慢慢看懂了表演。','Péngyou yìbiān gěi wǒ jiǎng gùshi, yìbiān pào chá, wǒmen mànman kàn dǒng le biǎoyǎn.','Bạn tôi vừa kể chuyện vừa pha trà, chúng tôi dần hiểu được buổi diễn.']], '“我”开始时对京剧了解多少？',['完全听懂','不懂唱词','看过很多次','会唱京剧'],1,'第一句明确说听不懂唱词。')], grammar: [point('hsk4-13-g1',['一边…一边…','一边 + V1，一边 + V2','Cùng một chủ thể thực hiện hai hành động đồng thời.','她一边喝茶，一边看书。','Tā yìbiān hē chá, yìbiān kàn shū.','Cô ấy vừa uống trà vừa đọc sách.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · HSK University (nguồn thứ cấp), 4B chưa xác minh', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-14-text','保护地球',[['保护环境不只是政府的事，每个人都能从小事做起。','Bǎohù huánjìng bù zhǐ shì zhèngfǔ de shì, měi ge rén dōu néng cóng xiǎoshì zuò qǐ.','Bảo vệ môi trường không chỉ là việc của chính phủ; mỗi người đều có thể bắt đầu từ việc nhỏ.'],['少用一次性用品、节约用水，做久了就会成为习惯。','Shǎo yòng yí cì xìng yòngpǐn, jiéyuē yòngshuǐ, zuò jiǔ le jiù huì chéngwéi xíguàn.','Hạn chế đồ dùng một lần, tiết kiệm nước; làm lâu dần sẽ thành thói quen.']], '作者建议怎样保护环境？',['等待别人行动','从日常小事做起','只参加宣传','少出门'],1,'Đoạn văn khuyến khích bắt đầu từ việc nhỏ hằng ngày.')], grammar: [point('hsk4-14-g1',['不只是…','不只是 + danh từ/động từ','Mở rộng phạm vi, cho biết sự việc không giới hạn ở điều vừa nêu.','保护环境不只是口号，也要落实到行动。','Bǎohù huánjìng bù zhǐ shì kǒuhào, yě yào luòshí dào xíngdòng.','Bảo vệ môi trường không chỉ là khẩu hiệu mà phải thành hành động.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · HSK University (nguồn thứ cấp), 4B chưa xác minh', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-15-text','教育孩子',[['孩子犯错时，父母先要听听他为什么这样做。','Háizi fàncuò shí, fùmǔ xiān yào tīngting tā wèishénme zhèyàng zuò.','Khi con mắc lỗi, cha mẹ trước tiên nên nghe xem vì sao con làm như vậy.'],['只批评不解释，孩子可能记住了害怕，却不知道怎样改正。','Zhǐ pīpíng bù jiěshì, háizi kěnéng jìzhù le hàipà, què bù zhīdào zěnyàng gǎizhèng.','Chỉ phê bình mà không giải thích, trẻ có thể chỉ nhớ nỗi sợ mà không biết sửa thế nào.']], '作者认为孩子犯错时父母应该先做什么？',['马上批评','听孩子解释','替孩子决定','不再管他'],1,'第一句建议先听孩子说明原因。')], grammar: [point('hsk4-15-g1',['不管…都…','不管 + tình huống，都 + kết quả','Kết quả không thay đổi dù điều kiện hoặc lựa chọn nào xảy ra.','不管孩子遇到什么问题，父母都应该耐心听。','Bùguǎn háizi yùdào shénme wèntí, fùmǔ dōu yīnggāi nàixīn tīng.','Dù con gặp vấn đề gì, cha mẹ cũng nên kiên nhẫn lắng nghe.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · HSK University (nguồn thứ cấp), 4B chưa xác minh', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-16-text','让生活更好',[['生活里有些问题暂时不能解决，但我们可以先改变自己的做法。','Shēnghuó li yǒuxiē wèntí zànshí bù néng jiějué, dàn wǒmen kěyǐ xiān gǎibiàn zìjǐ de zuòfǎ.','Một số vấn đề trong cuộc sống chưa thể giải quyết ngay, nhưng ta có thể thay đổi cách làm của mình trước.'],['每天给自己一点时间休息，心情也会慢慢变好。','Měitiān gěi zìjǐ yìdiǎn shíjiān xiūxi, xīnqíng yě huì mànman biàn hǎo.','Mỗi ngày dành cho mình chút thời gian nghỉ ngơi, tâm trạng cũng sẽ dần tốt lên.']], '文中建议怎样改善生活？',['马上换工作','每天留时间休息','不再安排计划','搬到别的城市'],1,'第二句 đưa ra gợi ý nghỉ ngơi mỗi ngày.')], grammar: [point('hsk4-16-g1',['不但…还…','不但 A，还 B','Vế hai bổ sung thêm một kết quả cùng hướng với vế đầu.','运动不但让身体健康，还能让心情变好。','Yùndòng búdàn ràng shēntǐ jiànkāng, hái néng ràng xīnqíng biàn hǎo.','Vận động không chỉ giúp cơ thể khỏe mà còn cải thiện tâm trạng.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · HSK University (nguồn thứ cấp), 4B chưa xác minh', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-17-text','人与自然',[['人和自然互相影响，森林减少以后，许多动物失去了生活的地方。','Rén hé zìrán hùxiāng yǐngxiǎng, sēnlín jiǎnshǎo yǐhòu, xǔduō dòngwù shīqù le shēnghuó de dìfang.','Con người và thiên nhiên tác động lẫn nhau; khi rừng giảm, nhiều động vật mất nơi sinh sống.'],['保护自然需要长期努力，也需要大家一起行动。','Bǎohù zìrán xūyào chángqī nǔlì, yě xūyào dàjiā yìqǐ xíngdòng.','Bảo vệ thiên nhiên cần nỗ lực lâu dài và mọi người cùng hành động.']], '保护自然需要什么？',['只靠一个人','长期努力和共同参与','停止所有工作','搬走动物'],1,'第二句指出需要长期努力并共同参与。')], grammar: [point('hsk4-17-g1',['随着…','随着 + danh từ/sự việc，mệnh đề','随着 dẫn bối cảnh thay đổi kéo theo một diễn biến khác.','随着城市发展，交通也变得更方便了。','Suízhe chéngshì fāzhǎn, jiāotōng yě biàn de gèng fāngbiàn le.','Cùng với sự phát triển của thành phố, giao thông cũng thuận tiện hơn.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · HSK University (nguồn thứ cấp), 4B chưa xác minh', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-18-text','科技改变生活',[['科技让我们更快地找到信息，也让远方的人容易联系。','Kējì ràng wǒmen gèng kuài de zhǎodào xìnxī, yě ràng yuǎnfāng de rén róngyì liánxì.','Công nghệ giúp ta tìm thông tin nhanh hơn và giúp người ở xa dễ liên lạc.'],['不过，如果一直看手机，人们也可能忽略身边的人。','Búguò, rúguǒ yìzhí kàn shǒujī, rénmen yě kěnéng hūlüè shēnbiān de rén.','Tuy vậy, nếu cứ nhìn điện thoại, con người cũng có thể bỏ quên những người bên cạnh.']], '科技带来什么问题？',['信息太少','可能忽略身边的人','联系变慢','不能找到资料'],1,'第二句说明持续看手机可能 khiến ta lơ là người xung quanh.')], grammar: [point('hsk4-18-g1',['不过','Mệnh đề， 不过 + mệnh đề','不过 dẫn ý đối lập nhẹ hoặc nêu giới hạn cho nhận định trước.','网上购物很方便，不过要注意商品质量。','Wǎngshàng gòuwù hěn fāngbiàn, búguò yào zhùyì shāngpǐn zhìliàng.','Mua sắm trực tuyến rất tiện, nhưng cần chú ý chất lượng hàng.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · HSK University (nguồn thứ cấp), 4B chưa xác minh', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-19-text','生活的味道',[['我小时候常跟奶奶做饭，她一边切菜一边告诉我家里的故事。','Wǒ xiǎoshíhou cháng gēn nǎinai zuò fàn, tā yìbiān qiē cài yìbiān gàosu wǒ jiālǐ de gùshi.','Hồi nhỏ tôi thường nấu ăn với bà; bà vừa thái rau vừa kể chuyện gia đình.'],['现在我自己做这道菜时，总会想起那些温暖的日子。','Xiànzài wǒ zìjǐ zuò zhè dào cài shí, zǒng huì xiǎngqǐ nàxiē wēnnuǎn de rìzi.','Giờ mỗi lần tự nấu món này, tôi lại nhớ những ngày tháng ấm áp ấy.']], '作者做这道菜时会想起什么？',['奶奶的故事和过去的日子','新的工作','一次旅行','学校生活'],0,'文中说做菜让作者想起过去温暖的日子。')], grammar: [point('hsk4-19-g1',['总会','总 + 会 + động từ','总会 biểu thị việc thường xuyên hoặc có khả năng lặp lại trong hoàn cảnh quen thuộc.','每次回家，我总会先给父母打电话。','Měi cì huí jiā, wǒ zǒng huì xiān gěi fùmǔ dǎ diànhuà.','Mỗi lần về nhà, tôi đều gọi điện cho cha mẹ trước.'])] },
  { sections: ['课文一 · website tự biên soạn', '课文二 · website tự biên soạn', '生词 · Từ mới', '语言点 · HSK University (nguồn thứ cấp), 4B chưa xác minh', '近义词辨析 · website biên soạn, chưa xác minh mục sách', '练习 · Bài tập'], dialogues: [], readings: [reading('hsk4-20-text','路上的风景',[['旅行时，我喜欢坐火车，因为可以慢慢看窗外的风景。','Lǚxíng shí, wǒ xǐhuan zuò huǒchē, yīnwèi kěyǐ mànman kàn chuāngwài de fēngjǐng.','Khi đi du lịch, tôi thích đi tàu vì có thể từ từ ngắm cảnh ngoài cửa sổ.'],['路程长一点儿也没关系，途中认识的人和看到的事也值得记住。','Lùchéng cháng yìdiǎnr yě méi guānxi, túzhōng rènshi de rén hé kàndào de shì yě zhídé jìzhù.','Quãng đường dài hơn một chút cũng không sao; những người gặp và việc thấy trên đường đều đáng nhớ.']], '作者为什么喜欢坐火车旅行？',['车票最便宜','可以慢慢看风景','不用带行李','很快到达'],1,'第一句说明坐火车可以慢慢看窗外风景。')], grammar: [point('hsk4-20-g1',['因为…','因为 + nguyên nhân，（所以）+ kết quả','因为 nêu lý do; 所以 có thể đưa ra kết quả tương ứng.','因为路上风景很好，所以我们走得很慢。','Yīnwèi lùshang fēngjǐng hěn hǎo, suǒyǐ wǒmen zǒu de hěn màn.','Vì cảnh trên đường rất đẹp nên chúng tôi đi rất chậm.'])] },
]

type SecondText = { title: string; sentences: ReadSeed[]; q: string; choices: string[]; answer: number; explain: string }

const confusable = (a: string, b: string, difference: string, x: Sentence, y: Sentence): ConfusablePair => ({ a, b, difference, examples: [x, y] })

