const HSK3_GRAMMAR_SUPPLEMENTS: Record<number, GSeed[]> = {
  1: [['介词 跟','A + 跟 + B (+ 一起) + V','跟 đặt người cùng tham gia sau chủ thể; 一起 nhấn mạnh làm chung.','我跟姐姐一起去书店。','Wǒ gēn jiějie yìqǐ qù shūdiàn.','Tôi cùng chị gái đi hiệu sách.'],['连词 那','Mệnh đề điều kiện/hoàn cảnh，那 + kết quả/đề nghị','那 nối điều vừa nêu với kết luận hoặc lời đề nghị tiếp theo.','你已经准备好了，那我们现在出发。','Nǐ yǐjīng zhǔnbèi hǎo le, nà wǒmen xiànzài chūfā.','Bạn chuẩn bị xong rồi, vậy chúng ta xuất phát nhé.']],
  2: [['Câu hỏi tu từ 能……吗？','能 + V + 吗？','Dùng 能……吗？ để hỏi tu từ rằng một việc có thể xảy ra hay không, thường hàm ý không thể.','这么晚了，我们能赶上末班车吗？','Zhème wǎn le, wǒmen néng gǎnshàng mòbānchē ma?','Muộn thế này, liệu chúng ta còn kịp chuyến cuối sao?']],
  3: [['会 biểu thị khả năng','Chủ ngữ + 会 + động từ','会 có thể nêu một khả năng có căn cứ hoặc dự đoán về sự việc.','认真练习以后，你会说得更自然。','Rènzhēn liànxí yǐhòu, nǐ huì shuō de gèng zìrán.','Sau khi luyện tập nghiêm túc, bạn sẽ nói tự nhiên hơn.']],
  5: [['可能 biểu thị khả năng','Chủ ngữ + 可能 + động từ/cụm vị ngữ','可能 đặt trước vị ngữ để nêu khả năng chưa chắc chắn.','他今天可能要晚一点儿到。','Tā jīntiān kěnéng yào wǎn yìdiǎnr dào.','Hôm nay có thể anh ấy sẽ đến muộn một chút.']],
  7: [['Cách nói thời gian 半、刻、差','半 / 一刻 / 差 + giờ','Các từ này bổ sung cách nói nửa giờ, một phần tư giờ và còn thiếu bao lâu đến giờ kế tiếp.','现在差一刻八点，我们快走吧。','Xiànzài chà yí kè bā diǎn, wǒmen kuài zǒu ba.','Bây giờ còn mười lăm phút nữa là tám giờ, chúng ta đi nhanh thôi.']],
  10: [['Chênh lệch mức độ với 多了','A + 比 + B + tính từ + 多了','多了 nhấn mạnh khoảng cách đáng kể giữa hai đối tượng trong phép so sánh.','今天比昨天暖和多了。','Jīntiān bǐ zuótiān nuǎnhuo duō le.','Hôm nay ấm hơn hôm qua nhiều.']],
  11: [['Số lượng ước chừng với 左右','Số lượng + 左右','左右 đặt sau số lượng để biểu thị con số xấp xỉ.','从我家到学校要走二十分钟左右。','Cóng wǒ jiā dào xuéxiào yào zǒu èrshí fēnzhōng zuǒyòu.','Từ nhà tôi đến trường đi bộ mất khoảng hai mươi phút.']],
  18: [['Giới từ 关于','关于 + chủ đề + mệnh đề','关于 đưa chủ đề được nhắc đến lên đầu cụm hoặc câu.','关于这次旅行，我们还要商量一下。','Guānyú zhè cì lǚxíng, wǒmen hái yào shāngliang yíxià.','Về chuyến đi lần này, chúng ta còn phải bàn thêm.']],
  20: [['Điều kiện giới hạn 只有……才……','只有 + điều kiện，才 + kết quả','只有 nêu điều kiện cần; 才 giới thiệu kết quả chỉ đạt được khi điều kiện ấy thỏa mãn.','只有每天复习，才能记住这些词。','Zhǐyǒu měitiān fùxí, cái néng jìzhù zhèxiē cí.','Chỉ khi ôn tập mỗi ngày mới có thể nhớ những từ này.']],
}

type SecondaryGrammarSeed = [title: string, pattern: string, hanzi: string, pinyin: string, vi: string]
const secondaryPoint = (id: string, [title, pattern, hanzi, pinyin, vi]: SecondaryGrammarSeed): GrammarPoint => point(id, [title, pattern, `Điểm ngữ pháp này trình bày cách dùng ${title}; hãy chú ý vị trí các thành phần theo mẫu.`, hanzi, pinyin, vi])

// Lesson-indexed HSKUniversity headings, mapped to HSK4B lessons 11–20.
